 if(id==="leak")return svg("Leak test pressure boundary and detector",'<rect x="115" y="78" width="360" height="115" rx="24" fill="'+tan+'" stroke="'+ink+'" stroke-width="3"/><path d="M475 125 H585" stroke="'+blue+'" stroke-width="5"/><rect x="585" y="88" width="90" height="75" rx="10" fill="'+wine+'"/><text x="630" y="130" text-anchor="middle" fill="#fff" font-size="13">Detector</text><circle cx="500" cy="125" r="8" fill="'+orange+'"/><text x="295" y="135" text-anchor="middle" fill="'+ink+'" font-size="17">Test volume</text>');
