 if(id==="probe")return svg("Probe transducer construction and acoustic beam",'<rect x="285" y="42" width="190" height="48" rx="8" fill="'+wine+'"/><text x="380" y="70" text-anchor="middle" fill="#fff" font-size="14">Probe housing</text><rect x="305" y="92" width="150" height="22" fill="'+orange+'"/><rect x="305" y="114" width="150" height="18" fill="'+blue+'"/><rect x="305" y="132" width="150" height="12" fill="'+wine+'"/><path d="M325 144 L240 215 M380 144 L380 215 M435 144 L520 215" stroke="'+blue+'" stroke-width="3" fill="none"/><text x="380" y="235" text-anchor="middle" fill="'+ink+'" font-size="13">Element, backing, matching layer and wear face shape the pulse</text>');
