 if(id==="materials")return svg("Material microstructure and manufacturing route",'<rect x="60" y="70" width="300" height="130" rx="8" fill="'+tan+'" stroke="'+ink+'" stroke-width="2"/>'+Array.from({length:7},(_,i)=>'<path d="M'+(60+i*45)+' 70 L'+(85+i*40)+' 200" stroke="'+wine+'" stroke-width="1.5"/>').join("")+'<path d="M360 135 H430" stroke="'+blue+'" stroke-width="4"/><rect x="440" y="70" width="260" height="130" rx="8" fill="#fff0e5" stroke="'+ink+'" stroke-width="2"/><path d="M475 105 Q520 70 560 105 T650 105 M475 150 Q520 115 560 150 T650 150" stroke="'+orange+'" stroke-width="3" fill="none"/><text x="210" y="45" text-anchor="middle" fill="'+ink+'" font-size="14">Grain structure</text><text x="570" y="45" text-anchor="middle" fill="'+ink+'" font-size="14">NDT response</text><text x="380" y="230" text-anchor="middle" fill="'+ink+'" font-size="13">Microstructure and process history change detectability</text>');
 if(id==="probe")return wave();
 return "";
